def flatten_nested(nested):
    """Flatten arbitrarily nested lists.

    >>> flatten_nested([1, [2, [3, []], 4]])
    [1, 2, 3, 4]
    """
    out = []
    for item in nested:
        if isinstance(item, list):
            out.extend(flatten_nested(item))
        else:
            out.append(item)
    return out
